\subsection*{Cross-section geometry and data}

\begin{definition}[Cross-sectional plane]
\label{def:IPhO2026Problems_problem_IPhO_2026_2_B_2:Plane}
\lean{IPhO2026.Problem2.B2.Plane}
The transverse cross-sectional plane $\mathbb{E}^2$ of the cooker.  The
physical system of Figure~2f is translationally invariant along the cylinder
axes, so a single cross-section captures all the geometry; points have units
of length.
\end{definition}
\begin{proof}
Definition; no claim.
\end{proof}

\begin{definition}[Cooker dimensionful parameters]
\label{def:IPhO2026Problems_problem_IPhO_2026_2_B_2:CookerParams}
\lean{IPhO2026.Problem2.B2.CookerParams}
The dimensionful parameters of the cooker of Figure~2f: the mirror radius
$R$ and the container radius $a$, both lengths and both certified positive
by bundled fields $0 < R$ and $0 < a$.
\end{definition}
\begin{proof}
Definition; no claim.
\end{proof}

\begin{definition}[Cooker cross-section geometry]
\label{def:IPhO2026Problems_problem_IPhO_2026_2_B_2:CookerGeometry}
\lean{IPhO2026.Problem2.B2.CookerGeometry}
\uses{def:IPhO2026Problems_problem_IPhO_2026_2_B_2:Plane, def:IPhO2026Problems_problem_IPhO_2026_2_B_2:CookerParams}
The geometry of the cross-section (Figure~2f): the mirror centre $C$, the
container centre $A$, the unit vector $e$ along the optical axis pointing
from $C$ towards the open half of the half-cylinder mirror, and the in-plane
unit normal $n$ (chosen on the container's side) perpendicular to $e$, with
the container centre lying $R/2$ from $C$ along $n$ on the symmetry axis:
$A - C = (R/2) \bullet n$.  Sunlight arrives in the direction $-e$.
\end{definition}
\begin{proof}
Definition; no claim.
\end{proof}

\begin{definition}[Mirror circle]
\label{def:IPhO2026Problems_problem_IPhO_2026_2_B_2:mirrorCircle}
\lean{IPhO2026.Problem2.B2.mirrorCircle}
\uses{def:IPhO2026Problems_problem_IPhO_2026_2_B_2:CookerParams, def:IPhO2026Problems_problem_IPhO_2026_2_B_2:CookerGeometry}
The full circle of radius $R$ centred at $C$ (the sphere of centre $C$ and
radius $R$ in the cross-sectional plane): the cross-sectional profile of the
cylinder mirror.
\end{definition}
\begin{proof}
Definition; no claim.
\end{proof}

\begin{definition}[Container disk]
\label{def:IPhO2026Problems_problem_IPhO_2026_2_B_2:containerDisk}
\lean{IPhO2026.Problem2.B2.containerDisk}
\uses{def:IPhO2026Problems_problem_IPhO_2026_2_B_2:CookerParams, def:IPhO2026Problems_problem_IPhO_2026_2_B_2:CookerGeometry}
The absorbing disk: the closed ball of centre $A$ and radius $a$, the
cross-section of the fully absorbing cylindrical container.
\end{definition}
\begin{proof}
Definition; no claim.
\end{proof}

\begin{definition}[Half-mirror arc]
\label{def:IPhO2026Problems_problem_IPhO_2026_2_B_2:halfMirrorArc}
\lean{IPhO2026.Problem2.B2.halfMirrorArc}
\uses{def:IPhO2026Problems_problem_IPhO_2026_2_B_2:mirrorCircle}
The half-cylinder mirror arc: the semicircle of
\cref{def:IPhO2026Problems_problem_IPhO_2026_2_B_2:mirrorCircle} lying in
the $0 \le \langle m - C, e\rangle$ half-plane --- the
``half-hollow-cylinder mirror'' of Figure~2f.
\end{definition}
\begin{proof}
Definition; no claim.
\end{proof}

\subsection*{Governing-law structures}

\begin{definition}[Absorbed-ray bookkeeping]
\label{def:IPhO2026Problems_problem_IPhO_2026_2_B_2:AbsorbedRays}
\lean{IPhO2026.Problem2.B2.AbsorbedRays}
\uses{def:IPhO2026Problems_problem_IPhO_2026_2_B_2:halfMirrorArc, def:IPhO2026Problems_problem_IPhO_2026_2_B_2:containerDisk}
Single-bounce bookkeeping for the sun rays absorbed by the container.  The
carrier pairs the incidence-point map $\mathrm{incidentPt} : \mathbb{R} \to
\mathbb{E}^2$ with the impact-parameter hit set; the bundled hypotheses
record the governing physical laws, kept as assumptions rather than
redefined locally: every absorbed ray (a) strikes the half-cylinder arc of
the mirror (incidence points land in
\cref{def:IPhO2026Problems_problem_IPhO_2026_2_B_2:halfMirrorArc}), (b)
obeys the specular reflection law on the circular profile --- the reflected
ray reaches an absorbed endpoint $q$ in
\cref{def:IPhO2026Problems_problem_IPhO_2026_2_B_2:containerDisk} with
$q - \mathrm{incidentPt}\,y = (2\langle \mathrm{incidentPt}\,y - C, n\rangle - R) \bullet n$;
and the Figure-2f branch information (c) the axial (central) ray is
absorbed, (d) the absorbed family is gap-free right of the axis
(contiguity of the single-bounce fan), and (e) every impact parameter in
$(0, a)$ is realized, so the collected fan fills one side from the axis to
the tangent ray and $\theta_{\max}$ is a maximum over a connected family.
\end{definition}
\begin{proof}
Definition; no claim.
\end{proof}

\begin{definition}[Collected width]
\label{def:IPhO2026Problems_problem_IPhO_2026_2_B_2:collectedWidth}
\lean{IPhO2026.Problem2.B2.collectedWidth}
\uses{def:IPhO2026Problems_problem_IPhO_2026_2_B_2:AbsorbedRays}
The transverse width (impact-parameter support) of the rays that the mirror
concentrates onto the container: the supremum of the axial readouts
$\langle \mathrm{incidentPt}\,y - C, e\rangle$ over the hit set.  With
uniform parallel sunlight this width is proportional to the received power
$P$ (per unit axial length).
\end{definition}
\begin{proof}
Definition; no claim.
\end{proof}

\begin{definition}[Uniform sunlight intensity]
\label{def:IPhO2026Problems_problem_IPhO_2026_2_B_2:UniformIntensity}
\lean{IPhO2026.Problem2.B2.UniformIntensity}
Uniform parallel sunlight: the incoming intensity $I$ (power per unit area)
is constant across the aperture and certified positive by a bundled field
$0 < I$.
\end{definition}
\begin{proof}
Definition; no claim.
\end{proof}

\begin{definition}[Power budget]
\label{def:IPhO2026Problems_problem_IPhO_2026_2_B_2:PowerBudget}
\lean{IPhO2026.Problem2.B2.PowerBudget}
\uses{def:IPhO2026Problems_problem_IPhO_2026_2_B_2:collectedWidth, def:IPhO2026Problems_problem_IPhO_2026_2_B_2:UniformIntensity, def:IPhO2026Problems_problem_IPhO_2026_2_B_2:CookerParams}
The power budget for the configuration: $P$, the power actually received by
the absorbing container from the mirror, and $P_0$, the power it would
receive without the mirror.  The bundled hypotheses state the physical
accounting under uniform intensity $I$: both quantities are proportional to
their transverse collected widths per unit axial length, namely
$P = I \cdot \mathrm{collectedWidth}$ and $P_0 = I \cdot (2a)$ (the
container's unmirrored geometric width, its diameter).
\end{definition}
\begin{proof}
Definition; no claim.
\end{proof}

\begin{definition}[B.1 calibration]
\label{def:IPhO2026Problems_problem_IPhO_2026_2_B_2:B1Calibration}
\lean{IPhO2026.Problem2.B2.B1Calibration}
\uses{def:IPhO2026Problems_problem_IPhO_2026_2_B_2:CookerParams}
The previous-part (B.1, $\alpha = R$, $\beta = -R/2$) result, kept as a
calibration hypothesis for the geometry: the container radius relates to the
maximum incidence angle by
$a = R \sin\theta - (R/2) \sin(2\theta)$.
\end{definition}
\begin{proof}
Definition; no claim.
\end{proof}

\begin{definition}[Incidence angle]
\label{def:IPhO2026Problems_problem_IPhO_2026_2_B_2:incidenceAngle}
\lean{IPhO2026.Problem2.B2.incidenceAngle}
\uses{def:IPhO2026Problems_problem_IPhO_2026_2_B_2:CookerParams, def:IPhO2026Problems_problem_IPhO_2026_2_B_2:CookerGeometry}
The incidence angle at a mirror point $m$ on the circular profile of radius
$R$, measured against the normal at $m$:
$\arccos\bigl(|\langle m - C, e\rangle| / R\bigr)$ --- the angle between
the incoming direction $e$ and the radius to $m$.
\end{definition}
\begin{proof}
Definition; no claim.
\end{proof}

\begin{definition}[Maximum incidence angle specification]
\label{def:IPhO2026Problems_problem_IPhO_2026_2_B_2:ThetaMaxSpec}
\lean{IPhO2026.Problem2.B2.ThetaMaxSpec}
\uses{def:IPhO2026Problems_problem_IPhO_2026_2_B_2:AbsorbedRays, def:IPhO2026Problems_problem_IPhO_2026_2_B_2:incidenceAngle}
The specification of $\theta_{\max}$: the largest angle of incidence on the
mirror (measured against the normal at the point of incidence) among all
reflected rays striking the container, lying in $(0, \pi/2)$ --- the branch
of nontrivial, non-grazing rays seen in Figure~2f.  Concretely: $\theta$ is
attained at some absorbed impact parameter and bounds the incidence angle
of every absorbed ray.
\end{definition}
\begin{proof}
Definition; no claim.
\end{proof}

\subsection*{Derivation bridges}

\begin{lemma}[Impact parameters bounded by the aperture]
\label{lem:IPhO2026Problems_problem_IPhO_2026_2_B_2:impactParam_le_aperture}
\lean{IPhO2026.Problem2.B2.impactParam\_le\_aperture}
\uses{def:IPhO2026Problems_problem_IPhO_2026_2_B_2:AbsorbedRays, def:IPhO2026Problems_problem_IPhO_2026_2_B_2:mirrorCircle}
Every mirror-collected impact parameter is bounded in absolute value by the
aperture radius: for every absorbed impact parameter $y$,
$|\langle \mathrm{incidentPt}\,y - C, e\rangle| \le R$.
\end{lemma}
\begin{proof}
The incidence point lies on the mirror circle, so
$\|\mathrm{incidentPt}\,y - C\| = R$; since $\|e\| = 1$, Cauchy--Schwarz
for the inner product gives
$|\langle \mathrm{incidentPt}\,y - C, e\rangle| \le
\|\mathrm{incidentPt}\,y - C\| \cdot \|e\| = R$.
\end{proof}

\begin{lemma}[Collected width equals the radius]
\label{lem:IPhO2026Problems_problem_IPhO_2026_2_B_2:collectedWidth_eq_radius}
\lean{IPhO2026.Problem2.B2.collectedWidth\_eq\_radius}
\uses{def:IPhO2026Problems_problem_IPhO_2026_2_B_2:collectedWidth, def:IPhO2026Problems_problem_IPhO_2026_2_B_2:AbsorbedRays, lem:IPhO2026Problems_problem_IPhO_2026_2_B_2:impactParam_le_aperture}
The transverse width collected by the half-cylinder mirror on the
container's side equals $R$ (one full half of the aperture $2R$):
$\mathrm{collectedWidth} = R$.
\end{lemma}
\begin{proof}
Upper bound: every impact-parameter readout is at most $R$ by
\cref{lem:IPhO2026Problems_problem_IPhO_2026_2_B_2:impactParam_le_aperture},
so the defining supremum does not exceed $R$.  Lower bound: the B.1
calibration with $\theta \in (0, \pi/2)$ gives $a \le R$, and full side
coverage together with the gap-free family realizes every impact parameter
in $(0, a)$ up to the aperture edge, forcing the supremum to be at least
$R$.
\end{proof}

\begin{lemma}[Power ratio as width ratio]
\label{lem:IPhO2026Problems_problem_IPhO_2026_2_B_2:power_ratio_eq_width_ratio}
\lean{IPhO2026.Problem2.B2.power\_ratio\_eq\_width\_ratio}
\uses{def:IPhO2026Problems_problem_IPhO_2026_2_B_2:PowerBudget, lem:IPhO2026Problems_problem_IPhO_2026_2_B_2:collectedWidth_eq_radius}
Power ratio from the width accounting only:
$P / P_0 = R / (2a)$.  With the B.1 calibration this becomes the target
trigonometric form.
\end{lemma}
\begin{proof}
Substitute the two budget identities
$P = I \cdot \mathrm{collectedWidth}$ and $P_0 = I \cdot (2a)$; the common
positive intensity $I$ cancels in the ratio, and
\cref{lem:IPhO2026Problems_problem_IPhO_2026_2_B_2:collectedWidth_eq_radius}
replaces $\mathrm{collectedWidth}$ by $R$.
\end{proof}

\begin{lemma}[Radius-over-diameter trigonometric bridge]
\label{lem:IPhO2026Problems_problem_IPhO_2026_2_B_2:radius_over_diameter_eq}
\lean{IPhO2026.Problem2.B2.radius\_over\_diameter\_eq}
\uses{def:IPhO2026Problems_problem_IPhO_2026_2_B_2:B1Calibration, def:IPhO2026Problems_problem_IPhO_2026_2_B_2:CookerParams}
Trigonometric bridge (B.1 calibration, elementary): for
$\theta \in (0, \pi/2)$ satisfying the calibration
$a = R \sin\theta - (R/2)\sin(2\theta)$,
\[
\frac{R}{2a} = \frac{1}{1 - \cos\theta} .
\]
\end{lemma}
\begin{proof}
Substitute the calibration and factor:
$2a = 2R\sin\theta - R\sin(2\theta)
= 2R\sin\theta\,(1 - \cos\theta)$ by the double-angle identity
$\sin(2\theta) = 2\sin\theta\cos\theta$.  Since $\theta \in (0, \pi/2)$,
$\sin\theta \ne 0$, so cancelling $R\sin\theta$ against the numerator $R$
leaves $R/(2a) = 1/(1 - \cos\theta)$.
\end{proof}

\subsection*{Target value theorem}

\begin{theorem}[Power ratio in terms of the maximum incidence angle]
\label{thm:IPhO2026Problems_problem_IPhO_2026_2_B_2:power_ratio_in_terms_of_theta_max}
\lean{IPhO2026.Problem2.B2.power\_ratio\_in\_terms\_of\_theta\_max}
\uses{def:IPhO2026Problems_problem_IPhO_2026_2_B_2:PowerBudget, def:IPhO2026Problems_problem_IPhO_2026_2_B_2:ThetaMaxSpec, def:IPhO2026Problems_problem_IPhO_2026_2_B_2:B1Calibration, lem:IPhO2026Problems_problem_IPhO_2026_2_B_2:power_ratio_eq_width_ratio, lem:IPhO2026Problems_problem_IPhO_2026_2_B_2:radius_over_diameter_eq}
\textbf{(Target, T2-B2.)}  For the cooker of Figure~2f with absorbed-ray
bookkeeping, power budget, and maximum incidence angle $\theta_{\max}$
satisfying
\cref{def:IPhO2026Problems_problem_IPhO_2026_2_B_2:ThetaMaxSpec} and the
B.1 calibration, the ratio of the received power $P$ to the unmirrored
power $P_0$ is
\[
\frac{P}{P_0} = \frac{1}{1 - \cos\theta_{\max}} .
\]
This is the recorded official answer of part B.2; the value is
conclusion-side only, confined to this target theorem (no hypothesis states
it in advance).
\end{theorem}
\begin{proof}
The specification
\cref{def:IPhO2026Problems_problem_IPhO_2026_2_B_2:ThetaMaxSpec} supplies
$\theta_{\max} \in (0, \pi/2)$, so
\cref{lem:IPhO2026Problems_problem_IPhO_2026_2_B_2:radius_over_diameter_eq}
applies under the B.1 calibration and gives
$R/(2a) = 1/(1 - \cos\theta_{\max})$; chaining with
\cref{lem:IPhO2026Problems_problem_IPhO_2026_2_B_2:power_ratio_eq_width_ratio},
$P/P_0 = R/(2a)$, yields the claim.
\end{proof}

